begin;
do $$declare actor uuid;r jsonb;v numeric;n bigint;begin
 select id into actor from public.profiles where role='admin' and status='active' order by id limit 1;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 r:=public.report_query('cash','1900-01-01','2099-12-31','{}',1,1);
 select coalesce((select sum(amount) from public.payments where status='valid' and payment_date>='1900-01-01T06:00:00Z' and payment_date<'2100-01-01T06:00:00Z'),0)+coalesce((select sum(amount) from public.manual_income where status='valid' and income_date>='1900-01-01T06:00:00Z' and income_date<'2100-01-01T06:00:00Z'),0)-coalesce((select sum(amount_crc) from public.expenses where status='valid' and expense_date>='1900-01-01T06:00:00Z' and expense_date<'2100-01-01T06:00:00Z'),0) into v;
 if v<>(r->'summary'->>'movimiento_neto_crc')::numeric then raise exception 'Cash mismatch';end if;
 r:=public.report_query('inventory','2026-01-01','2026-01-01','{}',1,5000);
 if exists(select 1 from jsonb_array_elements(r->'rows') j left join public.inventory_balances b on b.material_id=(j->>'id')::uuid where (j->>'existencia_actual')::numeric<>coalesce(b.quantity_on_hand,0)) then raise exception 'Stock mismatch';end if;
 select coalesce(sum(value_crc),0) into v from public.inventory_valuations;
 if round(v,2)<>(r->'summary'->>'importe_crc')::numeric then raise exception 'Valuation mismatch';end if;
 r:=public.report_query('hours','1900-01-01','2099-12-31','{}',1,1);
 if exists(select 1 from public.work_sessions where status<>'finished') then raise exception 'Run reconciliation without open test sessions';end if;
 select coalesce(sum(worked_seconds),0) into v from public.work_sessions where started_at>='1900-01-01T06:00:00Z' and finished_at<'2100-01-01T06:00:00Z';
 if v<>(r->'summary'->>'segundos_periodo')::numeric then raise exception 'Time mismatch';end if;
 r:=public.report_query('audit','1900-01-01','2099-12-31','{}',1,1);
 select count(*) into n from public.audit_log where created_at>='1900-01-01T06:00:00Z' and created_at<'2100-01-01T06:00:00Z';
 if n<>(r->>'count')::bigint then raise exception 'Audit mismatch';end if;
 r:=public.report_query('shipments','1900-01-01','2099-12-31','{}',1,1);
 select count(*) into n from public.shipments s cross join lateral(values(s.created_at),(s.shipped_at),(s.delivered_at),(s.cancelled_at)) x(t) where t>='1900-01-01T06:00:00Z' and t<'2100-01-01T06:00:00Z';
 if n<>(r->>'count')::bigint then raise exception 'Shipment mismatch';end if;
 r:=public.report_charts('1900-01-01','2099-12-31');
 select coalesce(sum(total),0) into v from public.orders where production_status='delivered' and delivered_at>='1900-01-01T06:00:00Z' and delivered_at<'2100-01-01T06:00:00Z';
 if v<>(select coalesce(sum((x->>'ventas_crc')::numeric),0) from jsonb_array_elements(r->'products') x) then raise exception 'Product series mismatch';end if;
 select coalesce(sum(amount_crc),0) into v from public.expenses where status='valid' and expense_date>='1900-01-01T06:00:00Z' and expense_date<'2100-01-01T06:00:00Z';
 if v<>(select coalesce(sum((x->>'gastos_crc')::numeric),0) from jsonb_array_elements(r->'categories') x) or v<>(select coalesce(sum((x->>'gastos_crc')::numeric),0) from jsonb_array_elements(r->'monthly') x) then raise exception 'Expense series mismatch';end if;
 raise notice 'PASS independent sources: cash, stock, valuation, hours, audit, shipment events';
end $$;
rollback;
